/** Boot auto-configuration in an offline web context, never SpringApplication or an embedded server. */
class SqlServerRuntimeRootTest {
    static Map<String,String> valid(){var values=new LinkedHashMap<String,String>();SqlServerRuntimePropertiesTest.values().forEach((key,value)->values.put(key,value.toString()));values.put("health.base-domain","health.localhost");values.put("health.public-origin","http://health.localhost:8080");values.put("health.session-hours","8");values.put("health.sqlserver.mode","runtime");values.put("spring.flyway.enabled","false");values.put("spring.sql.init.mode","never");values.put("management.endpoint.health.probes.enabled","true");values.put("management.endpoint.health.group.liveness.include","livenessState");values.put("management.endpoint.health.group.readiness.include","readinessState,db");return values;}
    static AnnotationConfigWebApplicationContext context(Map<String,String> values){var context=new AnnotationConfigWebApplicationContext();var environment=new MockEnvironment();values.forEach(environment::withProperty);context.setEnvironment(environment);context.setServletContext(new MockServletContext());context.register(SqlServerRuntimeRoot.class);return context;}
    static Object target(Object value){return AopTestUtils.getUltimateTargetObject(value);}
    static Object field(Object value,String name)throws Exception{Object target=target(value);var field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);}
    @AfterEach void clean(){RequestContextHolder.resetRequestAttributes();TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
    @Test void completeRootHas18ControllersMappingsSharedSqlGraphAndNoUnsafeInfrastructure()throws Exception{try(var drivers=mockConstruction(SQLServerDataSource.class);var context=context(valid())){context.refresh();assertEquals(18,context.getBeansWithAnnotation(RestController.class).size());assertEquals(1,context.getBeansOfType(Errors.Advice.class).size());var mapping=context.getBean("requestMappingHandlerMapping",RequestMappingHandlerMapping.class);var paths=new HashSet<String>();mapping.getHandlerMethods().keySet().forEach(info->paths.addAll(info.getPatternValues()));assertTrue(paths.containsAll(Set.of("/api/auth/login","/api/auth/browser/login","/api/public/status","/api/portal/patients","/api/support")));var access=context.getBean(Access.class);var identity=context.getBean(IdentityService.class);for(var entry:SqlServerBusinessConfigurationTest.SERVICES.entrySet()){assertEquals(1,context.getBeansOfType(entry.getKey()).size());var service=context.getBean(entry.getKey());assertSame(context.getBean(entry.getValue()),field(service,"store"));assertNull(field(service,"sql"));assertSame(access,field(service,"access"));}assertSame(identity,field(context.getBean(AccountLifecycleService.class),"identity"));assertSame(context.getBean(com.mavric.health.scheduling.application.SchedulingService.class),field(context.getBean(PortalService.class),"scheduling"));assertNull(field(context.getBean(PortalService.class),"sql"));assertEquals(1,context.getBeansOfType(Settings.class).size());var mapper=context.getBean(ObjectMapper.class);assertSame(mapper,field(context.getBean(Errors.class),"mapper"));var executor=context.getBean(SqlServerExecutor.class);assertSame(mapper,field(executor,"mapper"));var pool=context.getBean(HikariDataSource.class);assertSame(pool,context.getBean(JdbcTemplate.class).getDataSource());assertSame(pool,context.getBean(DataSourceTransactionManager.class).getDataSource());assertEquals(1,context.getBeansOfType(DataSource.class).size());assertEquals(1,context.getBeansOfType(PlatformTransactionManager.class).size());for(Class<?> store:SqlServerRuntimeStoresConfigurationTest.STORES){assertEquals(1,context.getBeansOfType(store).size());assertSame(executor,field(context.getBean(store),"executor"));}for(Class<?> type:List.of(Sql.class,AttemptRecorder.class,Bootstrap.class,SqlServerBootstrapStore.class,MailDelivery.class,org.springframework.mail.javamail.JavaMailSender.class,org.flywaydb.core.Flyway.class,com.mavric.health.audit.TraceFilter.class,HostFilter.class,SessionFilter.class))assertTrue(context.getBeansOfType(type).isEmpty(),type.getSimpleName());assertTrue(context.getBeansOfType(org.springframework.scheduling.annotation.ScheduledAnnotationBeanPostProcessor.class).isEmpty());assertTrue(context.getBeansOfType(org.springframework.scheduling.TaskScheduler.class).isEmpty());assertTrue(context.getBeansOfType(org.springframework.boot.sql.init.AbstractScriptDatabaseInitializer.class).isEmpty());assertTrue(context.getBeansOfType(MailDelivery.class).isEmpty());assertFalse(pool.isRunning());assertNull(pool.getHikariPoolMXBean());assertEquals(1,drivers.constructed().size());verify(drivers.constructed().getFirst(),never()).getConnection();verify(drivers.constructed().getFirst(),never()).getConnection(anyString(),anyString());assertFalse(((org.springframework.beans.factory.support.DefaultListableBeanFactory)context.getBeanFactory()).isAllowBeanDefinitionOverriding());}}
    @Test void readinessAndLivenessMembershipAndIndicatorAreExplicitWithoutProbeExecution()throws Exception{try(var drivers=mockConstruction(SQLServerDataSource.class);var context=context(valid())){context.refresh();var indicator=context.getBean("dbHealthIndicator",SqlServerDatabaseHealthIndicator.class);assertSame(context.getBean(SqlServerMonitorStore.class),field(indicator,"store"));assertEquals("livenessState",context.getEnvironment().getProperty("management.endpoint.health.group.liveness.include"));assertEquals("readinessState,db",context.getEnvironment().getProperty("management.endpoint.health.group.readiness.include"));var groups=context.getBean(org.springframework.boot.health.actuate.endpoint.HealthEndpointGroups.class);assertTrue(groups.get("liveness").isMember("livenessState"));assertFalse(groups.get("liveness").isMember("db"));assertTrue(groups.get("readiness").isMember("readinessState"));assertTrue(groups.get("readiness").isMember("db"));assertNull(context.getBean(HikariDataSource.class).getHikariPoolMXBean());verify(drivers.constructed().getFirst(),never()).getConnection();}}
    @Test void classProxyUsesDefaultSharedManagerAndRollsBackModeledServiceCallWithoutBorrowing()throws Exception{var model=new SqlServerIdentityStoreTest.ModelTransactionManager();var manager=mock(DataSourceTransactionManager.class);when(manager.getTransaction(any())).thenAnswer(inv->model.getTransaction(inv.getArgument(0)));doAnswer(inv->{model.commit(inv.getArgument(0));return null;}).when(manager).commit(any());doAnswer(inv->{model.rollback(inv.getArgument(0));return null;}).when(manager).rollback(any());try(var drivers=mockConstruction(SQLServerDataSource.class);var context=context(valid())){context.addBeanFactoryPostProcessor(factory->((AbstractBeanDefinition)factory.getBeanDefinition("transactionManager")).setInstanceSupplier(()->manager));context.refresh();var service=context.getBean(HospitalService.class);assertTrue(AopUtils.isCglibProxy(service));assertSame(manager,context.getBean("transactionManager"));assertSame(manager,context.getBean("sqlServerRuntimeTransactionManager"));var tx=(org.springframework.transaction.support.TransactionTemplate)field(context.getBean(SqlServerHospitalStore.class),"transactions");assertSame(manager,tx.getTransactionManager());var req=new MockHttpServletRequest();var actor=new Actor(SqlServerIdentityConfigurationTest.ID,"Synthetic","synthetic@example.test",SqlServerIdentityConfigurationTest.TENANT,List.of("ADM"),"a".repeat(64));req.setAttribute("health.actor",actor);req.setAttribute("health.tenant",new TenantRef(actor.tenantId(),"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("HOSPITAL")));RequestContextHolder.setRequestAttributes(new ServletRequestAttributes(req));TraceContext.REQUEST.set(req);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(actor,null,List.of()));assertEquals(400,assertThrows(ApiException.class,()->service.resource(null)).status);assertEquals(1,Collections.frequency(model.events,"begin:0"));assertEquals("rollback",model.events.getLast());verify(manager,atLeastOnce()).rollback(any());verify(drivers.constructed().getFirst(),never()).getConnection();}}
    @Test void rootIsOutsideLegacyScanAndAddsNoMainOrBootTestRoot(){assertTrue(new ClassPathScanningCandidateComponentProvider(true).findCandidateComponents("com.mavric.health").stream().noneMatch(bean->bean.getBeanClassName().startsWith("com.mavric.healthsqlserver.")));assertFalse(SqlServerRuntimeRoot.class.isAnnotationPresent(org.springframework.boot.SpringBootConfiguration.class));assertTrue(Arrays.stream(SqlServerRuntimeRoot.class.getDeclaredMethods()).noneMatch(method->method.getName().equals("main")));}
}
